const CATALOGS = { en, ja, zh };

// 欠落キーの警告は1回だけ（全言語共通）
const warnedMissing = new Set();

function formatParam(v) {
  if (v === null || v === undefined) return '-';
  if (typeof v === 'object') {
    try { return JSON.stringify(v); } catch { return String(v); }
  }
  return String(v);
}

// t(lang) → 翻訳関数 (key, params?) → string
// 選択言語に無いキーは en へフォールバック。en にも無ければキーを返し stderr に1回警告。
export function t(lang, defaults = {}) {
  const cat = Object.hasOwn(CATALOGS, lang) ? CATALOGS[lang] : CATALOGS.en;
  const defaultParams = { tokenName: 'COINU', tokenSymbol: 'COINU', ...defaults };
  function translate(key, params = {}) {
    const tpl = cat[key] ?? en[key];
    if (tpl == null) {
      if (!warnedMissing.has(key)) {
        warnedMissing.add(key);
        process.stderr.write(`[i18n] missing key: ${key}\n`);
      }
      return key;
    }
    const values = { ...defaultParams, ...(params || {}) };
    return tpl.replace(/\{(\w+)\}/g, (m, p) =>
      Object.prototype.hasOwnProperty.call(values, p) ? formatParam(values[p]) : '-'
    );
  }
  translate.setDefaults = (next = {}) => Object.assign(defaultParams, next);
  return translate;
}
